#nullable enable
using System;

static int QuantityOrDefault(string? input)
{
    return int.TryParse(input, out int quantity) && quantity > 0 ? quantity : 1;
}

Console.WriteLine(QuantityOrDefault("4"));
Console.WriteLine(QuantityOrDefault(null));
Console.WriteLine(QuantityOrDefault("oops"));

using System;
using System.Collections.Generic;

string[] pages = { "start", "notes", "start" };
var visits = new Dictionary<string, int>(StringComparer.Ordinal);
foreach (string page in pages)
{
    visits.TryGetValue(page, out int count);
    visits[page] = count + 1;
}

var keys = new List<string>(visits.Keys);
keys.Sort(StringComparer.Ordinal);
foreach (string key in keys)
{
    Console.WriteLine($"{key}: {visits[key]}");
}

using System;

var original = new Delivery("Cedar Street", 2);
var updated = original with { Parcels = 3 };

Console.WriteLine($"{original.Parcels} -> {updated.Parcels}");
Console.WriteLine(original == new Delivery("Cedar Street", 2));

record Delivery(string Address, int Parcels);

using System;
using System.Linq;

int[] prices = { 600, 125, 400, 300 };
int[] selected = prices.Where(price => price >= 300)
    .OrderBy(price => price)
    .ToArray();

Console.WriteLine(string.Join(", ", selected));
Console.WriteLine(selected.Sum());
